{"path":"/app/solve_seating.py","content":"from itertools import permutations

GUESTS = ["Alice", "Bob", "Charlie", "David", "Ethan", "Frankie"]
N = len(GUESTS)


def adjacent(pos, a, b):
    return (pos[a] - pos[b]) % N in (1, N - 1)


def across(pos, a, b):
    return (pos[a] - pos[b]) % N == N // 2


def two_left_of(pos, guest, reference):
    # Convention: seats increase to the left around the circular table.
    return pos[guest] == (pos[reference] + 2) % N


def two_right_of(pos, guest, reference):
    return pos[guest] == (pos[reference] - 2) % N


def valid(arrangement):
    pos = {guest: i for i, guest in enumerate(arrangement)}

    # Alice: Alice and Frankie work at rival companies; rivals cannot sit together.
    if adjacent(pos, "Alice", "Frankie"):
        return False

    # Bob: Bob sits two seats to Alice's left; Bob refuses to sit next to Ethan.
    if not two_left_of(pos, "Bob", "Alice"):
        return False
    if adjacent(pos, "Bob", "Ethan"):
        return False

    # Frankie: must sit next to at least one of David or Ethan.
    if not (adjacent(pos, "Frankie", "David") or adjacent(pos, "Frankie", "Ethan")):
        return False

    # Clue: if Ethan is across from Bob, David is two seats to Alice's right.
    if across(pos, "Ethan", "Bob") and not two_right_of(pos, "David", "Alice"):
        return False

    return True


def main():
    # Fix Alice at seat 0 to remove rotational duplicates.
    valid_arrangements = []
    for rest in permutations([g for g in GUESTS if g != "Alice"]):
        arrangement = ("Alice",) + rest
        if valid(arrangement):
            valid_arrangements.append(arrangement)

    pairs = set()
    for arrangement in valid_arrangements:
        idx = arrangement.index("Charlie")
        pair = tuple(sorted((arrangement[(idx - 1) % N], arrangement[(idx + 1) % N])))
        pairs.add(pair)

    print("valid arrangements:", len(valid_arrangements))
    for arrangement in valid_arrangements:
        print(arrangement)
    print("Charlie neighbor pairs:")
    for pair in sorted(pairs):
        print(f"{pair[0]}, {pair[1]}")


if __name__ == "__main__":
    main()
